code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    positions = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                positions[grid[r][c]] = (r, c)

    # Fixed motion associated with each marker color. Intermediate cells are 5.
    moves = {1: (-1, 2, "right_up"), 2: (0, -4, "left"),
             3: (3, 0, "down"), 6: (-6, 0, "up")}
    trails = {}
    for color, (r, c) in positions.items():
        if color not in moves:
            continue
        dr, dc, shape = moves[color]
        er, ec = r + dr, c + dc
        if not (0 <= er < h and 0 <= ec < w):
            continue
        if shape == "right_up":
            path = [(r, c+i) for i in range(1, dc+1)] + [(er, ec)]
        elif shape == "left":
            path = [(r, c-i) for i in range(1, -dc+1)]
        elif shape == "down":
            path = [(r+i, c) for i in range(1, dr+1)]
        else:
            path = [(r-i, c) for i in range(1, -dr+1)]
        for rr, cc in path:
            if 0 <= rr < h and 0 <= cc < w:
                if out[rr][cc] == 0:
                    out[rr][cc] = 5
        if out[er][ec] == 0:
            out[er][ec] = color
        trails[color] = path

    # Where the 2 and vertical marker trails meet, mark 4 and continue diagonally SW.
    if 2 in positions and any(x in positions for x in (3, 6)):
        r2, c2 = positions[2]
        for v in (3, 6):
            if v not in positions: continue
            rv, cv = positions[v]
            if cv == c2 and min(r2, rv) <= rv <= max(r2, rv):
                # Actual crossing of the horizontal 2 segment and vertical trajectory.
                cross = (r2, cv)
                if min(c2, c2-4) <= cv <= max(c2, c2-4) and min(rv, rv + moves[v][0]) <= r2 <= max(rv, rv + moves[v][0]):
                    rr, cc = cross
                    out[rr][cc] = 4
                    rr += 1; cc -= 1
                    while rr < h and cc >= 0:
                        if out[rr][cc] == 0: out[rr][cc] = 4
                        rr += 1; cc -= 1
                    break
    return out
'''
